17	/**
18	 * 事件及关联表（处置记录、交接单、状态历史）的 JDBC 仓储。
19	 * 所有写路径先以 FOR UPDATE 锁定事件行，保证同一事件的并发写按事务提交顺序生效。
20	 */
21	@Repository
22	public class IncidentRepository {
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public IncidentRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
29	
30	    private static final RowMapper<Incident> INCIDENT_MAPPER = (rs, n) -> mapIncident(rs);
31	    private static final RowMapper<IncidentAction> ACTION_MAPPER = (rs, n) -> new IncidentAction(
32	            rs.getLong("id"), rs.getLong("incident_id"), rs.getString("action_key"),
33	            rs.getString("action_type"), rs.getString("note"),
34	            rs.getTimestamp("occurred_at").toInstant(), rs.getString("actor"),
35	            rs.getTimestamp("created_at").toInstant());
36	    private static final RowMapper<IncidentTransfer> TRANSFER_MAPPER = (rs, n) -> new IncidentTransfer(
37	            rs.getLong("id"), rs.getLong("incident_id"), rs.getString("from_commander"),
38	            rs.getString("to_commander"), TransferStatus.valueOf(rs.getString("status")),
39	            rs.getTimestamp("created_at").toInstant(),
40	            rs.getTimestamp("accepted_at") == null ? null : rs.getTimestamp("accepted_at").toInstant());
41	    private static final RowMapper<StatusChange> STATUS_MAPPER = (rs, n) -> new StatusChange(
42	            rs.getLong("id"), rs.getLong("incident_id"),
43	            rs.getString("from_status") == null ? null : IncidentStatus.valueOf(rs.getString("from_status")),
44	            IncidentStatus.valueOf(rs.getString("to_status")),
45	            rs.getString("actor"), rs.getTimestamp("occurred_at").toInstant());
46	
47	    private static Incident mapIncident(ResultSet rs) throws SQLException {
48	        Timestamp deadline = rs.getTimestamp("deadline_at");
49	        return new Incident(rs.getLong("id"), rs.getString("incident_key"), rs.getString("severity"),
50	                rs.getString("summary"), rs.getString("reporter"),
51	                IncidentStatus.valueOf(rs.getString("status")), rs.getString("commander"),
52	                rs.getTimestamp("created_at").toInstant(), rs.getTimestamp("updated_at").toInstant(),
53	                deadline == null ? null : deadline.toInstant());
54	    }
55	
56	    /**
57	     * 按业务键查询事件（不加锁），用于只读场景。
58	     */
59	    public Optional<Incident> findByKey(String incidentKey) {
60	        List<Incident> rows = jdbc.query("SELECT * FROM incidents WHERE incident_key = ?",
61	                INCIDENT_MAPPER, incidentKey);
62	        return rows.stream().findFirst();
63	    }
64	
65	    /**
66	     * 按业务键查询并锁定事件行（SELECT ... FOR UPDATE），用于写路径串行化。
67	     */
68	    public Optional<Incident> lockByKey(String incidentKey) {
69	        List<Incident> rows = jdbc.query("SELECT * FROM incidents WHERE incident_key = ? FOR UPDATE",
70	                INCIDENT_MAPPER, incidentKey);
71	        return rows.stream().findFirst();
72	    }
73	
74	    /**
75	     * 插入新事件，初始状态 REPORTED、无指挥人、无遏制期限，返回生成主键。
76	     */
77	    public long insert(Incident incident) {
78	        KeyHolder keys = new GeneratedKeyHolder();
79	        jdbc.update(con -> {
80	            var ps = con.prepareStatement(
81	                    "INSERT INTO incidents (incident_key, severity, summary, reporter, status, commander,"
82	                            + " created_at, updated_at, deadline_at) VALUES (?,?,?,?,?,?,?,?,?)",
83	                    Statement.RETURN_GENERATED_KEYS);
84	            ps.setString(1, incident.incidentKey());
85	            ps.setString(2, incident.severity());
86	            ps.setString(3, incident.summary());
87	            ps.setString(4, incident.reporter());
88	            ps.setString(5, incident.status().name());
89	            ps.setString(6, incident.commander());
90	            ps.setTimestamp(7, Timestamp.from(incident.createdAt()));
91	            ps.setTimestamp(8, Timestamp.from(incident.updatedAt()));
92	            ps.setTimestamp(9, incident.deadlineAt() == null ? null : Timestamp.from(incident.deadlineAt()));
93	            return ps;
94	        }, keys);
95	        return keys.getKey().longValue();
96	    }
97	
98	    /**
99	     * 首次接管时写入遏制期限（只写一次，交接不重置）。
100	     */
101	    public void updateDeadline(long id, Instant deadlineAt, Instant updatedAt) {
102	        jdbc.update("UPDATE incidents SET deadline_at = ?, updated_at = ? WHERE id = ?",
103	                Timestamp.from(deadlineAt), Timestamp.from(updatedAt), id);
104	    }
105	
106	    /**
107	     * 更新事件状态与指挥人（commander 可为 null 表示不变更时传入原值）。
108	     */
109	    public void updateState(long id, IncidentStatus status, String commander, Instant updatedAt) {
110	        jdbc.update("UPDATE incidents SET status = ?, commander = ?, updated_at = ? WHERE id = ?",
111	                status.name(), commander, Timestamp.from(updatedAt), id);
112	    }
113	
114	    /**
115	     * 追加处置记录，返回生成主键。
116	     */
117	    public long insertAction(IncidentAction action) {
118	        KeyHolder keys = new GeneratedKeyHolder();
119	        jdbc.update(con -> {
120	            var ps = con.prepareStatement(
121	                    "INSERT INTO incident_actions (incident_id, action_key, action_type, note, occurred_at,"
122	                            + " actor, created_at) VALUES (?,?,?,?,?,?,?)",
123	                    Statement.RETURN_GENERATED_KEYS);
124	            ps.setLong(1, action.incidentId());
125	            ps.setString(2, action.actionKey());
126	            ps.setString(3, action.actionType());
127	            ps.setString(4, action.note());
128	            ps.setTimestamp(5, Timestamp.from(action.occurredAt()));
129	            ps.setString(6, action.actor());
130	            ps.setTimestamp(7, Timestamp.from(action.createdAt()));
131	            return ps;
132	        }, keys);
133	        return keys.getKey().longValue();
134	    }
