150	        return jdbc.query("SELECT * FROM incident_actions WHERE incident_id = ? ORDER BY id",
151	                ACTION_MAPPER, incidentId);
152	    }
153	
154	    /**
155	     * 创建交接单（PENDING），返回生成主键。
156	     */
157	    public long insertTransfer(IncidentTransfer transfer) {
158	        KeyHolder keys = new GeneratedKeyHolder();
159	        jdbc.update(con -> {
160	            var ps = con.prepareStatement(
