private void assertContainedStillSafe(Incident incident, RiskModel model, String barrierKey,
        String taskKey, int p, int q, boolean revoke) {
    if (incident.status() != IncidentStatus.CONTAINED) return;
    List<RiskBarrier> current = riskModels.listBarriers(incident.id());
    Map<String, TaskStatus> taskStatuses = taskStatuses(incident.id());
    BigInteger num = R; den = 1;
    for (RiskBarrier b : current) {
        if (b.revoked()) continue;
        String tk = b.taskKey(); int bn = b.numerator(); int bd = b.denominator();
        if (b.barrierKey().equals(barrierKey)) {
            if (revoke) continue;
            tk = taskKey; bn = p; bd = q;
        }
        if (taskStatuses.get(tk) == TaskStatus.DONE) {
            num = num.multiply(bd - bn); den = den.multiply(bd);
        }
    }
    if (num > L * den) throw ApiException.conflict("当前事件已 CONTAINED，变更后残余风险超限");
}
