private static BigInteger[] residualFraction(int initialRisk, List<RiskBarrier> barriers, Map<String,TaskStatus> statuses) {
    BigInteger num = BigInteger.valueOf(initialRisk);
    BigInteger den = BigInteger.ONE;
    for (b : barriers) {
        if (b.revoked()) continue;
        if (statuses.get(b.taskKey()) != TaskStatus.DONE) continue;
        num = num.multiply(BigInteger.valueOf(b.denominator() - b.numerator()));
        den = den.multiply(BigInteger.valueOf(b.denominator()));
    }
    BigInteger gcd = num.gcd(den);
    return new BigInteger[]{num.divide(gcd), den.divide(gcd)};
}
private static boolean withinLimit(int limit, BigInteger num, BigInteger den) {
    // num/den <= limit  ⟺  num <= limit*den  — but use unreduced? reduced is fine for comparison
    return num.compareTo(BigInteger.valueOf(limit).multiply(den)) <= 0;
}
```
