                .satisfies(e -> assertApiStatus(e, HttpStatus.NOT_FOUND));
        assertThatThrownBy(() -> register("INC-R3", "alice", "B-1", "T-1", 3, 2))
                .satisfies(e -> assertApiStatus(e, HttpStatus.BAD_REQUEST));
